# split each long path into straight segments (RDP)
def rdp(pts,eps=2.5):
    pts=np.array(pts,dtype=float)
    def rec(a,b):
        if b-a<2: return [a,b]
        p0,p1=pts[a],pts[b]
        v=p1-p0; L=np.linalg.norm(v)
        if L<1e-6:
